 // Applied Pharmacology: second 50-question batch (100 total).
 const pharmBatch2=[["Which factor affects drug distribution?","औषधिको distribution मा कुन कुराले असर गर्छ?",["Plasma protein binding","Hair colour","Room light","Shoe size"],"Protein binding and tissue perfusion affect distribution.","Protein binding र tissue perfusion ले distribution असर गर्छ।"],["Which organ metabolises most drugs?","धेरै औषधिको metabolism कुन अंगमा हुन्छ?",["Liver","Spleen","Thyroid","Skin"],"The liver is a major site of drug metabolism.","कलेजो औषधि metabolism को प्रमुख स्थान हो।"],["Many drugs are primarily excreted by the:","धेरै औषधि मुख्यतः कुन अंगबाट निस्कन्छन्?",["Kidney","Pancreas","Thyroid","Gallbladder"],"Renal impairment can cause drug accumulation.","मिर्गौला कमजोर हुँदा औषधि जम्मा हुन सक्छ।"],["A loading dose aims to:","Loading dose को उद्देश्य के हो?",["Reach target concentration rapidly","Prevent all side effects","Reverse every overdose","Stop metabolism"],"It rapidly achieves a target drug concentration.","यसले आवश्यक औषधि concentration छिटो पुर्‍याउँछ।"],["A maintenance dose aims to:","Maintenance dose को उद्देश्य के हो?",["Maintain therapeutic concentration","Cause immediate paralysis","Treat allergy only","Replace an antidote"],"It replaces drug eliminated over time.","समयसँगै निस्किएको औषधिको मात्रा पूर्ति गर्छ।"],["An adverse drug reaction is:","Adverse drug reaction भनेको के हो?",["Harmful unintended response","Desired therapeutic effect","Drug packaging defect only","Placebo response"],"It is a harmful unintended response at normal doses.","सामान्य dose मा हुने अनिच्छित हानिकारक प्रतिक्रिया हो।"],["First-line medicine for anaphylaxis is:","Anaphylaxis को first-line औषधि कुन हो?",["Epinephrine","Hydrocortisone alone","Antihistamine alone","Salbutamol alone"],"Epinephrine must not be delayed by adjunctive drugs.","सहायक औषधिका कारण epinephrine दिन ढिलाइ गर्नु हुँदैन।"],["Beta-2 receptor stimulation causes:","Beta-2 receptor सक्रिय हुँदा के हुन्छ?",["Bronchodilation","Vasoconstriction","Miosis","Platelet aggregation"],"Beta-2 stimulation relaxes bronchial smooth muscle.","Beta-2 सक्रिय हुँदा bronchial smooth muscle relax हुन्छ।"],["Phenylephrine is mainly a:","Phenylephrine मुख्यतः के हो?",["Alpha-1 agonist","Beta-2 agonist","Opioid agonist","Muscarinic blocker"],"Alpha-1 stimulation causes vasoconstriction.","Alpha-1 सक्रिय हुँदा vasoconstriction हुन्छ।"],["Metoprolol is relatively selective for:","Metoprolol कुन receptor का लागि तुलनात्मक रूपमा selective हो?",["Beta-1","Beta-2","Alpha-1","Muscarinic"],"Metoprolol is relatively beta-1 selective.","Metoprolol तुलनात्मक रूपमा beta-1 selective हो।"],["Enalapril belongs to which class?","Enalapril कुन समूहमा पर्छ?",["ACE inhibitor","Calcium-channel blocker","Loop diuretic","Opioid"],"Enalapril inhibits angiotensin-converting enzyme.","Enalapril ले ACE enzyme रोक्छ।"],["A common ACE inhibitor adverse effect is:","ACE inhibitor को सामान्य side effect कुन हो?",["Dry cough","Hearing loss","Constipation always","Bronchodilation"],"ACE inhibitors may cause cough and hyperkalaemia.","ACE inhibitor ले खोकी र potassium बढाउन सक्छ।"],["Patients starting ACE inhibitors may need monitoring of:","ACE inhibitor सुरु गर्दा के जाँच्नुपर्छ?",["Renal function and potassium","Hair colour","Visual acuity only","Stool pH"],"Creatinine/eGFR and potassium are commonly monitored.","Creatinine/eGFR र potassium निगरानी गरिन्छ।"],["Bumetanide is a:","Bumetanide कुन प्रकारको औषधि हो?",["Loop diuretic","Thiazide","Opioid","Antiplatelet"],"Bumetanide is a loop diuretic.","Bumetanide loop diuretic हो।"],["Mannitol is an:","Mannitol कुन प्रकारको औषधि हो?",["Osmotic diuretic","Opioid","Anticoagulant","Antihistamine"],"Mannitol is an osmotic diuretic.","Mannitol osmotic diuretic हो।"],["Omeprazole is a:","Omeprazole कुन समूहको औषधि हो?",["Proton pump inhibitor","H2 blocker","Opioid","Antiemetic"],"It suppresses gastric acid by inhibiting the proton pump.","यसले proton pump रोकेर gastric acid घटाउँछ।"],["Famotidine blocks:","Famotidine ले के block गर्छ?",["H2 receptors","Beta-1 receptors","Opioid receptors","Sodium channels"],"It blocks gastric H2 receptors.","यसले gastric H2 receptor block गर्छ।"],["Metoclopramide also has:","Metoclopramide को अर्को प्रभाव के हो?",["Prokinetic action","Anticoagulant action","Neuromuscular paralysis","Bronchodilation"],"It has dopamine D2 antagonism and prokinetic effects.","यसमा D2 antagonism र prokinetic प्रभाव हुन्छ।"],["Ondansetron may prolong the:","Ondansetron ले कुन interval बढाउन सक्छ?",["QT interval","PR interval only","ST segment always","RR interval"],"QT prolongation risk is relevant in susceptible patients.","जोखिम भएका बिरामीमा QT prolongation हुन सक्छ।"],["Paracetamol overdose primarily threatens the:","Paracetamol overdose ले मुख्यतः कुन अंगलाई क्षति गर्छ?",["Liver","Spleen","Thyroid","Skin"],"Overdose can cause severe hepatic injury.","Overdose ले कलेजोमा गम्भीर क्षति पुर्‍याउन सक्छ।"],["Ibuprofen is a:","Ibuprofen कुन औषधि हो?",["NSAID","Opioid","Anticoagulant","Antihistamine"],"Ibuprofen is a non-steroidal anti-inflammatory drug.","Ibuprofen NSAID हो।"],["NSAIDs may increase risk of:","NSAID ले कुन जोखिम बढाउन सक्छ?",["GI bleeding and renal injury","Bronchodilation","Hypoglycaemia always","Improved clotting"],"They can cause GI ulceration/bleeding and renal impairment.","यसले पेटमा ulcer/bleeding र kidney समस्या गराउन सक्छ।"],["Aspirin irreversibly inhibits platelet:","Aspirin ले platelet को कुन enzyme रोक्छ?",["COX-1","ACE","MAO","HMG-CoA reductase"],"COX-1 inhibition reduces thromboxane A2.","COX-1 रोक्दा thromboxane A2 घट्छ।"],["Clopidogrel blocks the platelet:","Clopidogrel ले platelet को कुन receptor रोक्छ?",["P2Y12 ADP receptor","Beta-2 receptor","H1 receptor","NMDA receptor"],"Clopidogrel is a P2Y12 antiplatelet drug.","Clopidogrel P2Y12 antiplatelet औषधि हो।"],["Tranexamic acid is:","Tranexamic acid कस्तो औषधि हो?",["Antifibrinolytic","Thrombolytic","Antibiotic","Diuretic"],"It inhibits fibrinolysis and helps stabilise clots.","यसले fibrinolysis रोक्दै clot स्थिर राख्न मद्दत गर्छ।"],["Unfractionated heparin is reversed by:","Unfractionated heparin को असर कुनले उल्ट्याउँछ?",["Protamine sulfate","Vitamin K","Naloxone","Flumazenil"],"Protamine neutralises unfractionated heparin.","Protamine ले unfractionated heparin neutralise गर्छ।"],["Vitamin K can reverse the effect of:","Vitamin K ले कुन औषधिको प्रभाव उल्ट्याउन सक्छ?",["Warfarin","Heparin","Aspirin","Dabigatran"],"Vitamin K supports synthesis of vitamin K-dependent clotting factors.","Vitamin K ले clotting factor synthesis पुनःस्थापित गर्न सहयोग गर्छ।"],["Apixaban directly inhibits:","Apixaban ले कुन factor रोक्छ?",["Factor Xa","Thrombin IIa","COX-1","Vitamin K reductase"],"Apixaban is a direct factor Xa inhibitor.","Apixaban direct factor Xa inhibitor हो।"],["Dabigatran directly inhibits:","Dabigatran ले कुन factor रोक्छ?",["Thrombin IIa","Factor Xa","Platelet COX-1","ACE"],"Dabigatran is a direct thrombin inhibitor.","Dabigatran direct thrombin inhibitor हो।"],["Budesonide inhaler is a:","Budesonide inhaler कुन औषधि हो?",["Corticosteroid","Beta blocker","Opioid","Anticoagulant"],"It reduces airway inflammation.","यसले airway inflammation घटाउँछ।"],["After inhaled corticosteroid use, the patient should:","Inhaled corticosteroid पछि बिरामीले के गर्नुपर्छ?",["Rinse the mouth","Lie flat immediately","Avoid water for a day","Take extra dose"],"Rinsing reduces oral candidiasis risk.","मुख कुल्ला गर्दा oral candidiasis जोखिम घट्छ।"],["Theophylline toxicity may cause:","Theophylline toxicity ले के गराउन सक्छ?",["Arrhythmias and seizures","Only mild thirst","Hair loss","Hypothermia"],"It has a narrow therapeutic range and serious toxicity.","यसको therapeutic range साँघुरो र toxicity गम्भीर हुन सक्छ।"],["Midazolam is a:","Midazolam कुन समूहको औषधि हो?",["Benzodiazepine","Opioid","Barbiturate","Local anaesthetic"],"Midazolam is a benzodiazepine sedative.","Midazolam benzodiazepine sedative हो।"],["Benzodiazepines enhance:","Benzodiazepine ले कुन प्रभाव बढाउँछ?",["GABA-A inhibitory activity","NMDA excitation","Thrombin activity","Histamine release"],"They positively modulate GABA-A receptors.","यसले GABA-A receptor को inhibitory प्रभाव बढाउँछ।"],["Combining opioids and benzodiazepines increases:","Opioid र benzodiazepine सँगै दिँदा के जोखिम बढ्छ?",["Respiratory depression","Alertness","Urine output","Blood clotting"],"Combined CNS depression can be life-threatening.","दुवैको CNS depression ले जीवन जोखिमको श्वास समस्या गराउन सक्छ।"],["Which volatile agent can trigger malignant hyperthermia?","कुन volatile agent ले malignant hyperthermia trigger गर्न सक्छ?",["Sevoflurane","Oxygen","Medical air","Nitrous oxide alone"],"Volatile anaesthetics can trigger MH in susceptible patients.","संवेदनशील बिरामीमा volatile anaesthetic ले MH trigger गर्न सक्छ।"],["Specific drug for malignant hyperthermia is:","Malignant hyperthermia को specific औषधि कुन हो?",["Dantrolene","Atropine","Naloxone","Protamine"],"Dantrolene is used with immediate supportive management.","Dantrolene सँगै तत्काल supportive management गरिन्छ।"],["Nitrous oxide should be avoided in:","Nitrous oxide कुन अवस्थामा नदिनु उपयुक्त हुन्छ?",["Pneumothorax","Simple abrasion","Myopia","Dental plaque"],"It can expand closed gas spaces.","यसले बन्द gas space ठूलो बनाउन सक्छ।"],["Desflurane is associated with:","Desflurane कुन प्रभावसँग सम्बन्धित छ?",["Airway irritation","Severe renal failure in all","Anticoagulation","Hypoglycaemia"],"It can irritate the airway and provoke coughing.","यसले airway irritation र खोकी गराउन सक्छ।"],["Procaine is which type of local anaesthetic?","Procaine कुन प्रकारको local anaesthetic हो?",["Ester","Amide","Opioid","Barbiturate"],"Procaine is an ester local anaesthetic.","Procaine ester local anaesthetic हो।"],["Bupivacaine toxicity is especially concerning due to:","Bupivacaine toxicity किन विशेष चिन्ताजनक छ?",["Cardiotoxicity","Antibiotic resistance","Insulin release","Anticoagulation"],"Systemic overdose may cause severe cardiac toxicity.","Systemic overdose ले गम्भीर cardiac toxicity गराउन सक्छ।"],["Severe local anaesthetic systemic toxicity may require:","गम्भीर local anaesthetic systemic toxicity मा के आवश्यक हुन सक्छ?",["IV lipid emulsion","Vitamin K","Oral iron","Insulin"],"IV lipid emulsion is part of recommended management for severe LAST.","गम्भीर LAST व्यवस्थापनमा IV lipid emulsion प्रयोग हुन्छ।"],["Atracurium may cause:","Atracurium ले के गराउन सक्छ?",["Histamine release","Opioid withdrawal","Hypoglycaemia","Anticoagulation"],"Histamine release can cause flushing and hypotension.","Histamine release ले flushing र hypotension गराउन सक्छ।"],["Cisatracurium undergoes:","Cisatracurium कुन प्रक्रियाबाट निस्कन्छ?",["Hofmann elimination","Renal filtration only","Hepatic activation only","Pulmonary excretion"],"Hofmann elimination is relatively organ-independent.","Hofmann elimination धेरै हदसम्म अंगमा निर्भर हुँदैन।"],["Atypical plasma cholinesterase can prolong paralysis from:","Atypical plasma cholinesterase ले कुन औषधिको paralysis लम्ब्याउन सक्छ?",["Suxamethonium","Rocuronium","Vecuronium","Cisatracurium"],"Reduced metabolism prolongs suxamethonium action.","Metabolism कम हुँदा suxamethonium को असर लम्बिन्छ।"],["Naloxone reverses:","Naloxone ले कुन औषधिको असर उल्ट्याउँछ?",["Opioids","Benzodiazepines","Heparin","Warfarin"],"Naloxone is an opioid receptor antagonist.","Naloxone opioid receptor antagonist हो।"],["Which is an antipyretic analgesic?","Antipyretic analgesic कुन हो?",["Paracetamol","Warfarin","Atropine","Furosemide"],"Paracetamol reduces fever and pain.","Paracetamol ले ज्वरो र दुखाइ घटाउँछ।"],["A medication reconciliation identifies:","Medication reconciliation ले के पत्ता लगाउँछ?",["Omissions and duplication","Patient's blood group","Only height","Only diagnosis"],"It identifies discrepancies and unintended differences in medication lists.","यसले औषधि छुटेको, दोहोरिएको र सूचीमा फरक पत्ता लगाउँछ।"],["Injectable preparation requires:","Injectable औषधि तयार गर्दा के आवश्यक छ?",["Aseptic technique","Reuse of needles","Unlabelled syringes","Mixing incompatible drugs"],"Aseptic technique and labelling reduce infection and medication errors.","Aseptic technique र labelling ले infection तथा medication error घटाउँछ।"],["Before IV administration, check:","IV औषधि दिनुअघि के जाँच्ने?",["Line patency and compatibility","Patient's shoe size","Room temperature only","Hair colour"],"Patency and compatibility reduce infiltration and interaction risks.","Line खुला र औषधि compatible छ कि छैन जाँच्दा जोखिम घट्छ।"],["Renally cleared medicines may accumulate when:","मिर्गौलाबाट निस्कने औषधि कुन अवस्थामा जम्मा हुन सक्छ?",["Renal function is reduced","Vision improves","Blood group changes","Height increases"],"Reduced renal clearance can cause accumulation and toxicity.","Renal clearance घट्दा औषधि जम्मा भएर toxicity हुन सक्छ।"]];
